/**
 * @name Unvalidated size from image header drives allocation
 * @description Sizes parsed from image headers control allocation sizes without upper bounds, enabling memory exhaustion
 * @kind problem
 * @problem.severity warning
 * @id py/pillow-unbounded-alloc
 * @tags security
 *        external/cwe/cwe-400
 *        external/cwe/cwe-770
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SizeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(Call c |
      source.asExpr() = c and
      c.getFunc().toString().regexpMatch("(.*\\.)?(i16|i32|i8|u8|u16|u32|unpack|getint|read)")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call c |
      sink.asExpr() = c.getArg(0) and
      c.getFunc().toString().regexpMatch("(.*\\.)?(tobytes|read|seek|decode|fill)$")
    )
  }
}

module SizeFlow = TaintTracking::Global<SizeConfig>;

from DataFlow::Node source, DataFlow::Node sink
where SizeFlow::flow(source, sink)
select sink, "Image header value $@ drives a size argument.", source, "parsed from image data"

/**
 * @name Dynamic attribute/method resolution from parsed data
 * @description Using getattr/setattr with names derived from parsed file content can reach unintended attributes
 * @kind problem
 * @problem.severity warning
 * @id py/pillow-dynamic-attr
 * @tags security
 *        external/cwe/cwe-470
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module AttrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(Call c |
      source.asExpr() = c and
      c.getFunc().toString().regexpMatch("(.*\\.)?(read|unpack|decode|i8|i16|i32|u8|u16|u32|getvalue)$")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::builtin(["getattr", "setattr", "__import__"]).getACall().getArg(1)
    or
    sink = API::moduleImport("operator").getMember("attrgetter").getACall().getArg(0)
  }
}

module AttrFlow = TaintTracking::Global<AttrConfig>;

from DataFlow::Node sink
where AttrFlow::flow(_, sink)
select sink, "Attribute name derived from parsed file content"
